public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k;
        freq[rem]++;
    }
    // remainder 0 must be even
    if (freq[0] % 2 != 0) {
        return false;
    }
    // for each remainder i, freq[i] must equal freq[k - i]
    for (int i = 1; i <= k / 2; i++) {
        if (i == k - i) { // special case when k is even and i == k/2
            if (freq[i] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[i] != freq[k - i]) {
                return false;
            }
        }
    }
    return true;
}

